CREATE TYPE "tipo_lancamento_enum" AS ENUM (
  'A PAGAR',
  'A RECEBER'
);

CREATE TYPE "tipo_pessoa_enum" AS ENUM (
  'CLIENTE',
  'FORNECEDOR'
);

CREATE TYPE "tipo_categoria_enum" AS ENUM (
  'RECEITA',
  'DESPESA'
);

CREATE TYPE "status_conta_enum" AS ENUM (
  'ABERTO',
  'VENCIDO',
  'PARCIAL',
  'LIQUIDADO',
  'CANCELADO'
);

CREATE TABLE "pessoas" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(150) NOT NULL,
  "tipo" tipo_pessoa_enum NOT NULL,
  "documento_federal" varchar(18),
  "ativo" boolean NOT NULL DEFAULT true,
  "criado_em" timestamp DEFAULT (now())
);

CREATE TABLE "categorias_financeiras" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(100) NOT NULL,
  "tipo" tipo_categoria_enum NOT NULL,
  "ativo" boolean NOT NULL DEFAULT true
);

CREATE TABLE "formas_pagamento" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(50) NOT NULL,
  "ativo" boolean NOT NULL DEFAULT true
);

CREATE TABLE "centros_custo" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" varchar(20) UNIQUE,
  "nome" varchar(100) NOT NULL,
  "ativo" boolean NOT NULL DEFAULT true
);

CREATE TABLE "contas_pagar_receber" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tipo_lancamento" tipo_lancamento_enum NOT NULL,
  "pessoa_id" integer NOT NULL,
  "numero_documento" varchar(50),
  "data_emissao" date NOT NULL,
  "data_vencimento" date NOT NULL,
  "valor_nominal" decimal(12,2) NOT NULL,
  "saldo_aberto" decimal(12,2) NOT NULL,
  "categoria_id" integer NOT NULL,
  "forma_pagamento_id" integer NOT NULL,
  "centro_custo_id" integer,
  "status" status_conta_enum NOT NULL DEFAULT 'ABERTO',
  "parcelamento" varchar(10),
  "juros_multa_previstos" decimal(5,2) DEFAULT 0,
  "observacoes" text,
  "justificativa_cancelamento" text,
  "criado_em" timestamp DEFAULT (now()),
  "atualizado_em" timestamp
);

COMMENT ON TABLE "pessoas" IS 'Cadastro compartilhado de Clientes e Fornecedores';

COMMENT ON COLUMN "pessoas"."tipo" IS 'RN01: Valida se é Cliente ou Fornecedor';

COMMENT ON COLUMN "pessoas"."documento_federal" IS 'CPF ou CNPJ';

COMMENT ON TABLE "categorias_financeiras" IS 'Classificação contábil/gerencial das contas';

COMMENT ON COLUMN "categorias_financeiras"."tipo" IS 'RN03: Receita ou Despesa';

COMMENT ON TABLE "formas_pagamento" IS 'Meio previsto ou utilizado para liquidação';

COMMENT ON COLUMN "formas_pagamento"."nome" IS 'Ex.: Boleto, Pix, Cartão';

COMMENT ON TABLE "centros_custo" IS 'Unidade ou departamento gerador da despesa/receita';

COMMENT ON TABLE "contas_pagar_receber" IS 'Tabela central de obrigações e direitos do módulo financeiro';

COMMENT ON COLUMN "contas_pagar_receber"."tipo_lancamento" IS 'A Pagar ou A Receber';

COMMENT ON COLUMN "contas_pagar_receber"."pessoa_id" IS 'RN01: Fornecedor (a pagar) ou Cliente (a receber)';

COMMENT ON COLUMN "contas_pagar_receber"."numero_documento" IS 'Número da NF, recibo ou duplicata';

COMMENT ON COLUMN "contas_pagar_receber"."data_vencimento" IS 'RN04: Base para status automático de Vencido';

COMMENT ON COLUMN "contas_pagar_receber"."valor_nominal" IS 'Valor original do lançamento (> 0)';

COMMENT ON COLUMN "contas_pagar_receber"."saldo_aberto" IS 'Saldo pendente para baixa';

COMMENT ON COLUMN "contas_pagar_receber"."categoria_id" IS 'RN03: Alinhada com a natureza da conta';

COMMENT ON COLUMN "contas_pagar_receber"."parcelamento" IS 'Ex.: 01/03';

COMMENT ON COLUMN "contas_pagar_receber"."justificativa_cancelamento" IS 'RN05: Obrigatória no delete lógico';

ALTER TABLE "contas_pagar_receber" ADD FOREIGN KEY ("pessoa_id") REFERENCES "pessoas" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "contas_pagar_receber" ADD FOREIGN KEY ("categoria_id") REFERENCES "categorias_financeiras" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "contas_pagar_receber" ADD FOREIGN KEY ("forma_pagamento_id") REFERENCES "formas_pagamento" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "contas_pagar_receber" ADD FOREIGN KEY ("centro_custo_id") REFERENCES "centros_custo" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE;
